//! Namespace identities are generated by the broker and tombstoned permanently.
use super::Service;
use crate::{Error, Result, capability::Peer, crypto, storage::*};
use secretsd_protocol::*;

impl Service {
    pub fn namespace(&self, id: NamespaceId) -> Result<NamespaceRecord> {
        let record = self.store.record::<NamespaceRecord>(NAMESPACE, &id.0)?;

        if !record.live || record.generation == 0 {
            return Err(Error::Denied);
        }

        Ok(record)
    }

    pub fn namespace_create(&mut self, peer: Peer) -> Result<NamespaceId> {
        if self.store.count(NAMESPACE, None) >= self.limits.namespaces {
            return Err(Error::Limit);
        }

        let id = NamespaceId(crypto::random_id()?);

        self.store.commit(
            AuditEvent::new(EventKind::NamespaceCreate, &id.0, &[], peer.uid, peer.pid),
            &[Change::put(
                NAMESPACE,
                &id.0,
                &NamespaceRecord {
                    generation: 1,
                    live: true,
                },
            )],
            None,
        )?;

        Ok(id)
    }

    pub fn namespace_delete(&mut self, id: NamespaceId, peer: Peer) -> Result<()> {
        let mut record = self.namespace(id)?;

        record.live = false;

        record.generation = record.generation.checked_add(1).ok_or(Error::Limit)?;

        self.store.commit(
            AuditEvent::new(EventKind::NamespaceDelete, &id.0, &[], peer.uid, peer.pid),
            &[Change::put(NAMESPACE, &id.0, &record)],
            None,
        )?;

        self.grants.revoke_namespace(id);

        Ok(())
    }

    pub fn recipient_generation(&self, id: RecipientId) -> Result<RecipientGeneration> {
        let record: RecipientRecord = self.store.record(RECIPIENT, &id.0)?;

        if record.generation == 0 {
            return Err(Error::Integrity);
        }

        Ok(RecipientGeneration(record.generation))
    }
}
